  # Result for a single prompt in a model evaluation run.
  class ApiModelEvaluationResult
    CONSTRUCTION_SURFACE = :named
    FIELDS = SdkInternalApiModelEvaluationResultMetadata::FIELDS
    REQUIRED_FIELDS = SdkInternalApiModelEvaluationResultMetadata::REQUIRED_FIELDS
    DECODERS = SdkInternalApiModelEvaluationResultMetadata::DECODERS

    # @return [String] Optional `string` value serialized in the `candidate_model_name` wire field.
    attr_reader :candidate_model_name
    # @return [String] Optional `string` value serialized in the `candidate_model_uuid` wire field.
    attr_reader :candidate_model_uuid
    # @return [String] Optional `string` value serialized in the `candidate_routed_task` wire field.
    attr_reader :candidate_routed_task
    # @return [Integer] Which pass over this dataset row produced this result, 1-indexed (1 = first pass). Always 0 (and omitted from JSON) when the run's epochs is 1 (the default) — per-attempt epoch numbering doesn't apply to single-pass runs. When epochs > 1, this always reflects epoch 1 (see epoch_results below).
    attr_reader :epoch
    # @return [Hash] Present only when the run's epochs > 1: every pass over this row — including epoch 1, duplicated here for convenience — keyed by 1-indexed "epoch1"/"epoch2"/"epoch3" labels. Mirrors the shape of the downloadable results file's epochResults object. The top-level fields above (output, metric_results, candidate_routed_task) always reflect epoch 1, so single-epoch clients reading only those fields see no difference when epochs > 1.
    attr_reader :epoch_results
    # @return [String] Optional `string` value serialized in the `ground_truth` wire field.
    attr_reader :ground_truth
    # @return [String] The input query sent to the candidate model.
    attr_reader :input
    # @return [Array_of_ApiEvaluationMetricResult] Per-metric scores and judge reasoning for this prompt.
    attr_reader :metric_results
    # @return [String] The response from the candidate model.
    attr_reader :output
    # @return [Integer] Which dataset row this result came from. Multiple results share a row_number when epochs > 1: one per pass over that row.
    attr_reader :row_number

    def initialize(**attributes)
      SdkModel.assign(self, attributes, FIELDS, REQUIRED_FIELDS)
      freeze
    end

    def self.from_hash(data)
      SdkModel.from_hash(self, data, FIELDS, REQUIRED_FIELDS, DECODERS)
    end

    def to_h
      SdkModel.to_h(self, FIELDS)
    end
  end
end
